import Image from "next/image";
import brandAssets from "@/config/brand-assets.json";

type Variant = "horizontal" | "vertical" | "symbol";

const SOURCES = {
  horizontal: brandAssets["latansa-logo-horizontal"]["960"],
  vertical: brandAssets["latansa-logo-vertical"]["960"],
  symbol: brandAssets["latansa-symbol"]["512"],
} as const;

interface BrandLogoProps {
  variant: Variant;
  className?: string;
  priority?: boolean;
}

/**
 * Official LATANSA logo, rendered from derivatives of the originals in
 * assets/brand (generated by `npm run brand:assets`). Never recolor, filter,
 * stretch or re-compose the artwork — size it with width + `h-auto` only.
 *
 * - horizontal: navbar and compact headers
 * - vertical: selected corporate-identity compositions
 * - symbol: favicon/app icon contexts only
 */
export function BrandLogo({ variant, className, priority }: BrandLogoProps) {
  const src = SOURCES[variant];
  return (
    <Image
      src={src.png}
      width={src.width}
      height={src.height}
      alt="LATANSA — CV Latansa Jogjakarta"
      priority={priority}
      className={className}
    />
  );
}
